-- RootishArrayStack：由逻辑下标定位块号及块内下标。
INSERT INTO knowledge_point (name, description, course_id, parent_id, content_key, content_source, content_version, content_review_status, sort_order, deleted)
SELECT 'RootishArrayStack 的下标到块映射', '逻辑下标 i 的块号 b=ceil((-3+sqrt(9+8i))/2)，块内下标 j=i-b(b+1)/2。', course.id, parent.id, 'ods-rootisharraystack-index-mapping', 'AISTU', 1, 'REVIEWED', 30, 0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-stacks-queues-arrays' LEFT JOIN knowledge_point existing ON existing.content_key='ods-rootisharraystack-index-mapping' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id, content_key, content_version, review_status, title, lesson_json, check_json)
SELECT point.id, 'ods-rootisharraystack-index-mapping', 1, 'REVIEWED', 'RootishArrayStack 的下标到块映射', JSON_OBJECT('summary','对逻辑下标 i，块号 b 是满足 (b+1)(b+2)/2≥i+1 的最小非负整数，即 ceil((-3+sqrt(9+8i))/2)；块内下标为 i-b(b+1)/2。','steps',JSON_ARRAY('用累计容量确定 i 所在的最小块号 b','块 b 之前共有 b(b+1)/2 个槽位','减去此前容量得到块内下标 j','get/set 可直接访问 blocks[b][j]'),'prerequisite',JSON_OBJECT('contentKey','ods-rootisharraystack-block-layout','title','RootishArrayStack 的递增块布局','description','先理解块容量按 1、2、…递增。'),'nextStep',JSON_OBJECT('contentKey','ods-rootisharraystack-update','title','RootishArrayStack 的按位插入与删除','description','继续学习跨块按全局下标搬移元素。')), JSON_OBJECT('id','rootisharraystack-index-mapping-v1','prompt','计算块内下标 j 前，必须先从逻辑下标 i 中减去什么？','options',JSON_ARRAY(JSON_OBJECT('id','PREVIOUS_CAPACITY','text','所有先前块的累计容量 b(b+1)/2'),JSON_OBJECT('id','CURRENT_CAPACITY','text','当前块的容量 b+1')),'correctOptionId','PREVIOUS_CAPACITY','correctExplanation','正确：块 b 之前已有 b(b+1)/2 个槽位，减去它才得到块内偏移。','incorrectExplanation','不正确：当前块容量不能表示此前逻辑元素的数量。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='ods-rootisharraystack-index-mapping' AND existing.content_version=1 WHERE point.content_key='ods-rootisharraystack-index-mapping' AND existing.id IS NULL;
